*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/elw_recv_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
scwin.vScrenID = "ULDSTF05905.xml";
scwin.clickBzProcsNo = "";
scwin.readOnlyYn = "Y";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_set_code = function() {
    dts_ElwInst.DataID = "/CodeAction.do?method=listWrntCd&For=R";
    dts_ElwInst.Reset();
    //alert("call");

};
scwin.fn_list_sync = function() {
    var urlcond = '';
    urlcond += "&ISUR_CD=" + $c.stf.getObjectValue(cmb_ISUR_CD);
    urlcond += "&LIST_PROCS_STAT_CD=" + $c.stf.getObjectValue(cmb_LIST_PROCS_STAT_CD);
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        var url = "/ElwListedReceive.do?method=listElwNewListing&inputMessageId=ELW_LISTING_PROC_INOUT";
        url += urlcond;
        //alert("vListMdCd :"+vListMdCd);
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_List_1.DataID = encodeURI(url);
        dts_List_1.Reset();
        $c.cm.ShowWin(grd_List_1);
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        var url = "/ElwListedReceive.do?method=listElwAddNewListing&inputMessageId=ELW_LISTING_PROC_INOUT";
        url += urlcond;
        //alert("vListMdCd :"+vListMdCd);
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_List_2.DataID = encodeURI(url);
        dts_List_2.Reset();
        $c.cm.ShowWin(grd_List_2);
    }
};
scwin.fn_setBzProcsNo = function(obj, dtsObj) {
    scwin.clickBzProcsNo = dtsObj.getCellData(eval(obj), "BZ_PROCS_NO");
};
scwin.fn_OpenDetail = function(row, dtsObj) {
    scwin.fn_setBzProcsNo(row, dtsObj);
    var vbzTpCd = dtsObj.getCellData(row, "LIST_BZ_TP_CD");
    $c.elw.fn_OpenDetailRecv(vbzTpCd);
};
scwin.fn_getbzTpCd = function() {
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        vLIST_BZ_TP_CD = LIST_BZ_TP_CD_003;
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        vLIST_BZ_TP_CD = LIST_BZ_TP_CD_005;
    }
    return vLIST_BZ_TP_CD;
};
scwin.fn_getPopWindowNm = function() {
    var screenNm;
    scwin.fn_getbzTpCd();
    if (vLIST_BZ_TP_CD == LIST_BZ_TP_CD_003) {
        screenNm = "신규상장";
    } else if (vLIST_BZ_TP_CD == LIST_BZ_TP_CD_005) {
        screenNm = "추가상장";
    }
    return screenNm;
};
scwin.fn_OpenDetailListDD = async function() {
    await $c.frame.CreateDialogFrame("ULDSTF05906", "/lstproc/ULDSTF05906.gfm", scwin.fn_getPopWindowNm() + " 상장일지정", 260, 110, 630, 440, "window");
};
scwin.fn_OpenDetailDscl = async function() {
    await $c.frame.CreateDialogFrame("ULDSTF05907", "/lstproc/ULDSTF05907.gfm", scwin.fn_getPopWindowNm() + " 안내문작성", 260, 60, 535, 670, "window");
};


/********************************************** 
 * 함수명   : fn_ExcelDown()
 * 설명       : 정보를 excel로 다운 받는다.
 ***********************************************/
scwin.fn_ExcelDown = function() {
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        $c.data.downloadGridViewExcel(grd_List_1, "신규상장처리", "", "8");
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        $c.data.downloadGridViewExcel(grd_List_2, "추가상장처리", "", "8");
    }
};
scwin.btn_ListDd_onclick = function() {
    scwin.fn_OpenDetailListDD();
};
scwin.btn_Dscl_onclick = function() {
    scwin.fn_OpenDetailDscl();
};
scwin.MaxTab_01_OnSelChanged = function(nIndex) {
    scwin.fn_list_sync();
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    scwin.fn_ExcelDown();
};
scwin.dts_List_1_OnLoadError = function() {
    $c.stf.alert_error(dts_List_1);
};
scwin.dts_List_2_OnLoadError = function() {
    $c.stf.alert_error(dts_List_2);
};
scwin.dts_List_1_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List_1);
};
scwin.dts_List_2_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List_2);
};
scwin.grd_List_1_OnDblClick = function(row, colid) {
    //if (colid=='ISU_KOR_ABBRV'){
    scwin.fn_OpenDetail(row, dts_List_1);
    //}

};
scwin.grd_List_2_OnDblClick = function(row, colid) {
    //if (colid=='ISU_KOR_ABBRV'){
    scwin.fn_OpenDetail(row, dts_List_2);
    //}

};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    MaxTab_01.setSelectedTabIndex(1);
    $c.cm.PanelToGroupBox(panel_Top);
    scwin.fn_set_code();
    scwin.fn_list_sync();
};
